import numpy as np
from scipy.optimize import least_squares
e=df['eps'].values;T=df['T'].values;s=df['sigma'].values
ss=float(np.sum((s-s.mean())**2))
models={
'H': lambda p: p[0]*e**p[1]*T**p[2]+p[3]*e**p[4]*np.exp(-p[5]*T)+p[6]*np.exp(-p[7]*T)+p[8]*e**p[9],
'I': lambda p: p[0]*e*T**p[1]+p[2]*e**p[3]*np.exp(-p[4]*T)+p[5]*np.exp(-p[6]*T)+p[7]*e**p[8]*T**p[9],
}
rng=np.random.default_rng(7)
for name,m in models.items():
    best=[1e9,None]
    for i in range(6):
        p0=rng.normal(0,1,10)
        for idx in ([1,3,9] if name=='H' else [3,8]):
            p0[idx]=abs(p0[idx])+0.5
        for idx in ([5,7] if name=='H' else [4,6]):
            p0[idx]=abs(p0[idx])+0.2
        try:
            r=least_squares(lambda p: m(p)-s,p0,max_nfev=200)
            v=float(np.sum(r.fun**2))/ss
            if np.isfinite(v) and v<best[0]: best=[v,r.x]
        except Exception: pass
    print(name,best[0],np.round(best[1],4).tolist())

